The following native_sim C code for an embedded system has a bug.
Category: isr-concurrency — Lock-Free Single-Producer Single-Consumer Queue

## Buggy Code

```c
/*
 * Lock-free SPSC ring queue for Zephyr RTOS.
 * Power-of-2 buffer with atomic indices — no locks required.
 */

#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>

#define QUEUE_SIZE 16  /* MUST be power of 2 */
#define QUEUE_MASK (QUEUE_SIZE - 1)

struct spsc_queue {
	uint8_t    buf[QUEUE_SIZE];
	uint32_t   write_idx;
	uint32_t   read_idx;
};

static struct spsc_queue q;

static int spsc_push(struct spsc_queue *q, uint8_t val)
{
	uint32_t w = q->write_idx;
	uint32_t r = q->read_idx;

	/* Check full: queue holds at most QUEUE_SIZE-1 items */
	if ((uint32_t)(w - r) >= QUEUE_SIZE) {
		return -1; /* full */
	}

	q->buf[w & QUEUE_MASK] = val;

	/* Ensure write is visible before advancing the index */
	compiler_barrier();
	q->write_idx = w + 1;
	return 0;
}

static int spsc_pop(struct spsc_queue *q, uint8_t *val)
{
	uint32_t r = q->read_idx;
	uint32_t w = q->write_idx;

	if (r == w) {
		return -1; /* empty */
	}

	*val = q->buf[r & QUEUE_MASK];

	/* Ensure read is complete before advancing the index */
	compiler_barrier();
	q->read_idx = r + 1;
	return 0;
}

int main(void)
{
	uint8_t val;

	q.write_idx = 0;
	q.read_idx = 0;

	spsc_push(&q, 0xAB);
	spsc_push(&q, 0xCD);

	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", val);
	}
	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", val);
	}
	if (spsc_pop(&q, &val) != 0) {
		printk("Queue empty as expected\n");
	}

	return 0;
}

```

## Bug Hint

Plain uint32_t indices instead of atomic_t — data race between ISR and thread

## Task

Find and fix the bug in the code above.
Output ONLY the complete corrected C source file.

