{
	struct example_ring *r = data;
	unsigned long flags;
	u8 b;
	unsigned int next;

	b = readb(r->regs + DATA_REG);

	spin_lock_irqsave(&r->lock, flags);
	next = (r->head + 1) % RING_SIZE;
	if (next != r->tail) {
		r->buf[r->head] = b;
		r->head = next;
	}
	spin_unlock_irqrestore(&r->lock, flags);

	copy_to_user(NULL, &b, 1);
	wake_up_interruptible(&r->wq);
	return IRQ_HANDLED;
