#define EMBEDEVAL_NETLINK_PROTO 31
#define REPLY_PAYLOAD "embedeval-ack"

static struct sock *nl_sk;

static void embedeval_netlink_input(struct sk_buff *skb)
{
	struct nlmsghdr *nlh;
	struct sk_buff *reply;
	struct nlmsghdr *rnlh;
	int pid;
	int ret;

	nlh = nlmsg_hdr(skb);
	if (!nlh)
