	rnlh = nlmsg_put(reply, 0, 0, NLMSG_DONE, sizeof(REPLY_PAYLOAD), 0);
	if (!rnlh) {
		nlmsg_free(reply);
		return;
	}

	memcpy(nlmsg_data(rnlh), REPLY_PAYLOAD, sizeof(REPLY_PAYLOAD));

	ret = netlink_unicast(nl_sk, reply, pid, 0);
	if (ret < 0)
